const input = $json.body ?? $json;

const text = (value) =>
  value === null || value === undefined
    ? ''
    : String(value).trim();

const bool = (value) =>
  typeof value === 'boolean'
    ? value
    : ['true', '1', 'yes', 'on'].includes(
        text(value).toLowerCase()
      );

const dry_run = bool(
  input.dry_run === undefined
    ? true
    : input.dry_run
);

const batch_size = Number(input.batch_size ?? 5000);

const fields = {
  permission_check_retention_days:
    Number(input.permission_check_retention_days ?? 90),

  delivery_event_retention_days:
    Number(input.delivery_event_retention_days ?? 180),

  message_attempt_retention_days:
    Number(input.message_attempt_retention_days ?? 180),

  audit_retention_days:
    Number(input.audit_retention_days ?? 365),

  resolved_error_retention_days:
    Number(input.resolved_error_retention_days ?? 180),

  health_snapshot_retention_days:
    Number(input.health_snapshot_retention_days ?? 90),

  maintenance_run_retention_days:
    Number(input.maintenance_run_retention_days ?? 90),
};

const confirm_cleanup = bool(input.confirm_cleanup);
const errors = [];

if (
  !Number.isInteger(batch_size) ||
  batch_size < 1 ||
  batch_size > 100000
) {
  errors.push({
    field: 'batch_size',
    message: 'اندازه Batch معتبر نیست.',
  });
}

for (const [field, value] of Object.entries(fields)) {
  if (
    !Number.isInteger(value) ||
    value < 7 ||
    value > 3650
  ) {
    errors.push({
      field,
      message: 'Retention باید بین 7 و 3650 روز باشد.',
    });
  }
}

if (confirm_cleanup !== true) {
  errors.push({
    field: 'confirm_cleanup',
    message: 'اجرای Cleanup باید تأیید شود.',
  });
}

return [{
  json: {
    dry_run,
    batch_size,
    ...fields,
    confirm_cleanup,
    validation_status:
      errors.length === 0 ? 'valid' : 'invalid',
    errors,
  },
}];
